which node; node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
// Read SQLite header to confirm it's a valid DB
console.log('File size:', buf.length);
console.log('Header:', buf.slice(0, 16).toString('ascii'));
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');
// Check users table schema
console.log('=== users ===');
const usersInfo = db.prepare('PRAGMA table_info(users)').all();
console.log(usersInfo.map(c => c.name));

// Check ts_contacts schema
console.log('\n=== ts_contacts ===');
const contactsInfo = db.prepare('PRAGMA table_info(ts_contacts)').all();
console.log(contactsInfo.map(c => c.name));

// Check ob_users schema
console.log('\n=== ob_users ===');
const obInfo = db.prepare('PRAGMA table_info(ob_users)').all();
console.log(obInfo.map(c => c.name));
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Get self contact from ts_contacts
console.log('=== ts_contacts (self) ===');
const selfContact = db.prepare('SELECT * FROM ts_contacts WHERE is_self = 1').all();
console.log(selfContact);

// Also show all contacts for context
console.log('\n=== All ts_contacts ===');
const allContacts = db.prepare('SELECT * FROM ts_contacts').all();
console.log(allContacts);
"
